package fixture

import "sync"

type Counter struct {
	mu    sync.RWMutex
	count int
}

func (c *Counter) Add() {
	c.mu.Lock()
	c.count++
	c.mu.Unlock()
}

func (c *Counter) Snapshot() int {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return c.count
}

package fixture

import "context"

func Process(ctx context.Context, values []string, visit func(string)) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	for _, value := range values {
		visit(value)
	}
	return nil
}

package fixture

import "strings"

func VisibleNames(names []string) []string {
	visible := make([]string, 0, len(names))
	for _, name := range names {
		if strings.TrimSpace(name) == "" {
			continue
		}
		visible = append(visible, name)
	}
	return visible
}

package fixture

import (
	"context"
	"errors"
)

type Client interface {
	Fetch(context.Context, string) (string, error)
}

func Refresh(ctx context.Context, client Client, key string, maxAttempts int) (string, error) {
	if maxAttempts < 1 {
		return "", errors.New("no attempts")
	}
	var lastErr error
	for attempt := 0; attempt < maxAttempts; attempt++ {
		value, err := client.Fetch(ctx, key)
		if err == nil {
			return value, nil
		}
		lastErr = err
	}
	return "", lastErr
}

package fixture

import (
	"errors"
	"sync"
)

type Sender interface {
	Send(string) error
}

type Submitter struct {
	seen   sync.Map
	sender Sender
}

func (s *Submitter) Submit(requestID string) error {
	if _, loaded := s.seen.LoadOrStore(requestID, struct{}{}); loaded {
		return errors.New("duplicate request")
	}
	return s.sender.Send(requestID)
}

package fixture

import "context"

type Policy interface {
	Allows(context.Context, string, string) (bool, error)
}

type Repository interface {
	Open(context.Context, string) ([]byte, error)
}

func Read(ctx context.Context, policy Policy, repository Repository, actor, documentID string) ([]byte, error) {
	allowed, err := policy.Allows(ctx, actor, documentID)
	if err != nil {
		return nil, err
	}
	if !allowed {
		return nil, nil
	}
	return repository.Open(ctx, documentID)
}

package fixture

import (
	"context"
	"errors"
)

type Claims struct {
	Subject string
}

type Verifier interface {
	Verify(context.Context, string) (Claims, error)
}

func Authenticate(ctx context.Context, verifier Verifier, token string) (Claims, error) {
	claims, err := verifier.Verify(ctx, token)
	if err != nil {
		return Claims{}, err
	}
	if claims.Subject == "" {
		return Claims{}, errors.New("missing subject")
	}
	return claims, nil
}

package fixture

import "context"

func Publish(ctx context.Context, out chan<- string, values []string) error {
	for _, value := range values {
		select {
		case out <- value:
		case <-ctx.Done():
			return ctx.Err()
		}
	}
	return nil
}

