package fixture

type Status int

const (
	StatusQueued Status = iota
	StatusDone
)

func StatusLabel(status Status) string {
	switch status {
	case StatusQueued:
		return "queued"
	case StatusDone:
		return "done"
	default:
		return "unknown"
	}
}

